// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;

    function setUp() public {
        c = new RoundFactory();
    }

    function testFuzz_property(address fuzzedActor) public {
        vm.assume(fuzzedActor != address(0));
        vm.prank(fuzzedActor);
        c.initialize();

        address ownerBefore = c.owner();
        bool success;
        vm.prank(ownerBefore);
        try c.renounceOwnership() {
            success = true;
        } catch {
            success = false;
        }

        assertTrue(success && c.owner() == address(0));
    }
}
